INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(1477, 20, 0, 'esMX', 'Todavía tengo las cicatrices de esa noche.'),
(1477, 21, 0, 'esMX', '¿Esa fue la tercera o cuarta vez que casi me destripan tratando una de tus locuras?'),
(1477, 22, 0, 'esMX', 'Tengo un pedazo de hierro en la espalda que me va a recordar esa noche por el resto de mis días.'),
(1477, 23, 0, 'esMX', 'Y gracias por dejarme cargar mi propia mano hasta los sacerdotes esa noche.'),
(1477, 24, 0, 'esMX', 'Me rompí las dos piernas esa noche. ¿Cómo me voy a olvidar?'),
(1477, 25, 0, 'esMX', '¿No fue esa la noche que tuvimos que juntar mi pulgar y llevarlo en tu bolsa de tabaco?'),
(1477, 26, 0, 'esMX', 'Desperté en una cama en la Vega Norteña tres semanas después. No me acuerdo de nada.'),
(1477, 50, 0, 'esMX', 'Una taberna cálida y una cerveza fría. ¿Qué más podríamos pedir?'),
(1478, 20, 0, 'esMX', '¡Ah, los mellizos Glustewelt!'),
(1478, 21, 0, 'esMX', 'Peleando contra esa banda del Martillo Crepuscular en el Fangal, se me ocurren mejores lugares para una guerra.'),
(1478, 22, 0, 'esMX', 'Extraño la cerveza enana que tomábamos en esa posada en Lordaeron. ¿Te acordás de la pelea que empezamos ahí?'),
(1478, 23, 0, 'esMX', 'Menos de cien de nosotros, contra más de mil orcos. Solo un puñado logramos salir con vida de esa.'),
(1478, 24, 0, 'esMX', '¿Te acordás cuando Danath juntó a todos los mercenarios de Ventormenta y marchamos a pelear a Nethergarde?'),
(1478, 25, 0, 'esMX', 'Lo mejor fue la cara de Perenolde cuando nuestro ejército llegó marchando justo hasta la puerta de su casa. ¡Qué batalla!'),
(1478, 26, 0, 'esMX', 'Les digo, no extraño para nada la Gran Guerra. Me acuerdo cuando peleamos en Darrowmere. Toda la noche en la niebla, tirados en una zanja embarrada.'),
(1478, 30, 0, 'esMX', 'Bueno, seguís aquí. Yo diría que eso vale la pena brindar por ello.'),
(1478, 31, 0, 'esMX', 'Gritaste como una nena, lo más gracioso que vi en mi vida.'),
(1478, 32, 0, 'esMX', 'Nunca vi a nadie moverse tan rápido en toda mi vida.'),
(1478, 33, 0, 'esMX', 'Mejor ni empecemos a comparar cicatrices de batalla, amigo.'),
(1478, 34, 0, 'esMX', 'Jeje, blandengue.'),
(1478, 35, 0, 'esMX', 'No dejás de sorprenderme con lo que una persona puede sobrevivir.'),
(1478, 36, 0, 'esMX', 'Al final todo salió bien.'),
(1478, 50, 0, 'esMX', 'Oye Reese, danos otra ronda a Christoph y a mí.'),
(1477, 20, 0, 'esES', 'Todavía tengo las cicatrices de aquella noche.'),
(1477, 21, 0, 'esES', '¿No fue esa la tercera o cuarta vez que casi me destripan intentando una de tus locuras?'),
(1477, 22, 0, 'esES', 'Tengo un trozo de hierro en la espalda que me recordará esa noche el resto de mis días.'),
(1477, 23, 0, 'esES', 'Sí, y gracias por dejarme llevar mi propia mano hasta los sacerdotes aquella noche.'),
(1477, 24, 0, 'esES', 'Me rompí las dos piernas aquella noche. ¿Cómo iba a olvidarlo?'),
(1477, 25, 0, 'esES', '¿No fue esa la noche en que tuvimos que recoger mi pulgar y llevarlo en tu bolsa de tabaco?'),
(1477, 26, 0, 'esES', 'Desperté en una cama en Vigilia Norte tres semanas después. No recuerdo nada.'),
(1477, 50, 0, 'esES', 'Una taberna cálida y una cerveza fría. ¿Qué más podríamos pedir?'),
(1478, 20, 0, 'esES', '¡Ah, los gemelos Glustewelt!'),
(1478, 21, 0, 'esES', 'Luchando contra esa banda del Martillo Crepuscular en el Cenagal, se me ocurren mejores lugares para una guerra.'),
(1478, 22, 0, 'esES', 'Echo de menos la cerveza enana que tomábamos en aquella posada de Lordaeron. ¿Recuerdas la pelea que empezamos allí?'),
(1478, 23, 0, 'esES', 'Menos de cien de los nuestros, contra más de mil orcos. Solo un puñado logramos salir con vida de aquello.'),
(1478, 24, 0, 'esES', '¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a luchar a Nethergarde?'),
(1478, 25, 0, 'esES', 'Lo mejor fue la cara de Perenolde cuando nuestro ejército llegó marchando hasta la puerta de su casa. ¡Menuda batalla!'),
(1478, 26, 0, 'esES', 'Te lo digo, no echo de menos la Gran Guerra en absoluto. Recuerdo cuando luchamos en Darrowmere. Toda la noche entre la niebla, tirados en una trinchera embarrada.'),
(1478, 30, 0, 'esES', 'Bueno, sigues aquí. Yo diría que eso merece un brindis.'),
(1478, 31, 0, 'esES', 'Gritaste como una niña, lo más gracioso que he visto en mi vida.'),
(1478, 32, 0, 'esES', 'Nunca vi a nadie moverse tan rápido en toda mi vida.'),
(1478, 33, 0, 'esES', 'Mejor no empecemos a comparar cicatrices de batalla, amigo.'),
(1478, 34, 0, 'esES', 'Je, blandengue.'),
(1478, 35, 0, 'esES', 'No dejas de sorprenderme con lo que una persona puede sobrevivir.'),
(1478, 36, 0, 'esES', 'Al final todo salió bien.'),
(1478, 50, 0, 'esES', 'Oye Reese, ponnos otra ronda a Christoph y a mí.'),
(1477, 20, 0, 'deDE', 'Ich habe immer noch die Narben von dieser Nacht.'),
(1477, 21, 0, 'deDE', 'War das nicht das dritte oder vierte Mal, dass ich bei einer deiner verrückten Aktionen fast aufgeschlitzt wurde?'),
(1477, 22, 0, 'deDE', 'Ich habe ein Stück Eisen im Rücken, das mich für den Rest meiner Tage an diese Nacht erinnern wird.'),
(1477, 23, 0, 'deDE', 'Ja, und danke, dass ich meine eigene Hand zu den Priestern tragen durfte, in jener Nacht.'),
(1477, 24, 0, 'deDE', 'Habe mir in jener Nacht beide Beine gebrochen. Wie könnte ich das vergessen?'),
(1477, 25, 0, 'deDE', 'War das nicht die Nacht, in der wir meinen Daumen aufsammeln und in deinem Tabakbeutel tragen mussten?'),
(1477, 26, 0, 'deDE', 'Ich bin drei Wochen später in einem Bett in Nordhain aufgewacht. Erinnere mich an gar nichts mehr.'),
(1477, 50, 0, 'deDE', 'Eine warme Taverne und ein kaltes Ale. Was könnten wir uns mehr wünschen?'),
(1478, 20, 0, 'deDE', 'Ah, die Glustewelt-Zwillinge!'),
(1478, 21, 0, 'deDE', 'Als wir gegen diese Bande vom Dämmerhammer im Morast gekämpft haben, fielen mir bessere Orte für einen Krieg ein.'),
(1478, 22, 0, 'deDE', 'Ich vermisse das Zwergenbier, das wir immer in jenem Gasthaus in Lordaeron getrunken haben. Erinnerst du dich an die Schlägerei, die wir dort angefangen haben?'),
(1478, 23, 0, 'deDE', 'Weniger als hundert von uns, gegen über tausend Orcs. Nur eine Handvoll von uns hat es geschafft, davonzukommen.'),
(1478, 24, 0, 'deDE', 'Erinnerst du dich, als Danath alle Söldner Sturmwinds versammelt hat und wir nach Nethergarde marschiert sind, um zu kämpfen?'),
(1478, 25, 0, 'deDE', 'Das Beste war der Blick auf Perenoldes Gesicht, als unsere Armee direkt vor seiner Haustür aufmarschiert ist. Was für eine Schlacht!'),
(1478, 26, 0, 'deDE', 'Ich sag dir, den Großen Krieg vermisse ich überhaupt nicht. Ich erinnere mich, als wir bei Darrowmere gekämpft haben. Die ganze Nacht im Nebel, in einem schlammigen Graben liegend.'),
(1478, 30, 0, 'deDE', 'Nun, du bist immer noch hier. Ich würde sagen, darauf sollten wir trinken.'),
(1478, 31, 0, 'deDE', 'Du hast wie ein kleines Mädchen geschrien, das Lustigste, was ich je gesehen habe.'),
(1478, 32, 0, 'deDE', 'Habe noch nie jemanden so schnell rennen sehen in meinem ganzen Leben.'),
(1478, 33, 0, 'deDE', 'Lass uns gar nicht erst anfangen, Kampfnarben zu vergleichen, mein Freund.'),
(1478, 34, 0, 'deDE', 'Hehe, Weichei.'),
(1478, 35, 0, 'deDE', 'Du überraschst mich ständig damit, was ein Mensch überleben kann.'),
(1478, 36, 0, 'deDE', 'Am Ende hat sich alles gefügt.'),
(1478, 50, 0, 'deDE', 'Hey Reese, gib mir und Christoph noch eine Runde.'),
(1477, 20, 0, 'frFR', 'J\'ai toujours les cicatrices de cette nuit-là.'),
(1477, 21, 0, 'frFR', 'C\'était la troisième ou quatrième fois que je manquais de me faire éventrer en essayant une de tes folies?'),
(1477, 22, 0, 'frFR', 'J\'ai un morceau de fer dans le dos qui me rappellera cette nuit-là jusqu\'à la fin de mes jours.'),
(1477, 23, 0, 'frFR', 'Ouais, et merci de m\'avoir laissé porter ma propre main jusqu\'aux prêtres, cette nuit-là.'),
(1477, 24, 0, 'frFR', 'Je me suis cassé les deux jambes cette nuit-là. Comment pourrais-je oublier?'),
(1477, 25, 0, 'frFR', 'N\'était-ce pas la nuit où on a dû ramasser mon pouce et le porter dans ta blague à tabac?'),
(1477, 26, 0, 'frFR', 'Je me suis réveillé dans un lit à Rives-Septentrion trois semaines plus tard. Je ne me souviens de rien.'),
(1477, 50, 0, 'frFR', 'Une taverne chaleureuse et une bière fraîche. Que demander de plus?'),
(1478, 20, 0, 'frFR', 'Ah, les jumeaux Glustewelt!'),
(1478, 21, 0, 'frFR', 'En combattant cette bande du Marteau du Crépuscule dans le Marécage, je voyais de meilleurs endroits pour une guerre.'),
(1478, 22, 0, 'frFR', 'La bière naine qu\'on buvait dans cette auberge à Lordaeron me manque. Tu te souviens de la bagarre qu\'on a déclenchée là-bas?'),
(1478, 23, 0, 'frFR', 'Moins d\'une centaine d\'entre nous, contre plus d\'un millier d\'orcs. Seule une poignée d\'entre nous a réussi à s\'en sortir.'),
(1478, 24, 0, 'frFR', 'Tu te souviens quand Danath a rassemblé tous les mercenaires de Hurlevent et qu\'on a marché pour combattre à Nethergarde?'),
(1478, 25, 0, 'frFR', 'Le meilleur moment, c\'était la tête de Perenolde quand notre armée est arrivée en marchant droit jusqu\'à sa porte. Quelle bataille!'),
(1478, 26, 0, 'frFR', 'Je te le dis, la Grande Guerre ne me manque pas du tout. Je me souviens quand on s\'est battus à Darrowmere. Toute la nuit dans le brouillard, couchés dans une tranchée boueuse.'),
(1478, 30, 0, 'frFR', 'Eh bien, tu es toujours là. Je dirais que ça vaut bien un verre.'),
(1478, 31, 0, 'frFR', 'Tu as crié comme une fillette, la chose la plus drôle que j\'aie jamais vue.'),
(1478, 32, 0, 'frFR', 'Je n\'ai jamais vu personne bouger aussi vite de toute ma vie.'),
(1478, 33, 0, 'frFR', 'Ne commençons même pas à comparer nos cicatrices de guerre, mon ami.'),
(1478, 34, 0, 'frFR', 'Hého, mauviette.'),
(1478, 35, 0, 'frFR', 'Tu n\'arrêtes pas de me surprendre par ce qu\'une personne peut survivre.'),
(1478, 36, 0, 'frFR', 'Tout s\'est bien terminé, au final.'),
(1478, 50, 0, 'frFR', 'Hé Reese, sers-nous une autre tournée, à Christoph et moi.'),
(1477, 20, 0, 'ruRU', 'У меня до сих пор остались шрамы с той ночи.'),
(1477, 21, 0, 'ruRU', 'Это был третий или четвёртый раз, когда меня чуть не выпотрошили во время одной из твоих безумных выходок?'),
(1477, 22, 0, 'ruRU', 'У меня в спине застрял кусок железа, который будет напоминать мне о той ночи до конца моих дней.'),
(1477, 23, 0, 'ruRU', 'Ага, и спасибо, что позволил мне самому донести свою руку до жрецов той ночью.'),
(1477, 24, 0, 'ruRU', 'Сломал обе ноги в ту ночь. Как я могу забыть?'),
(1477, 25, 0, 'ruRU', 'Не в ту ли ночь нам пришлось подобрать мой большой палец и нести его в твоём кисете для табака?'),
(1477, 26, 0, 'ruRU', 'Я очнулся в постели в Северном Крае три недели спустя. Ничего не помню.'),
(1477, 50, 0, 'ruRU', 'Тёплая таверна и холодный эль. Что ещё нам нужно?'),
(1478, 20, 0, 'ruRU', 'Ах, близнецы Глюствельт!'),
(1478, 21, 0, 'ruRU', 'Сражаясь с той бандой Сумеречного Молота в Трясине, я бы придумал место получше для войны.'),
(1478, 22, 0, 'ruRU', 'Скучаю по дворфийскому элю, который мы пили в той таверне в Лордероне. Помнишь драку, что мы там затеяли?'),
(1478, 23, 0, 'ruRU', 'Меньше сотни нас против более чем тысячи орков. Лишь горстке из нас удалось выбраться живыми.'),
(1478, 24, 0, 'ruRU', 'Помнишь, как Данат собрал всех наёмников Штормграда, и мы отправились сражаться к Нетергарде?'),
(1478, 25, 0, 'ruRU', 'Лучше всего было выражение лица Перенольда, когда наша армия подошла прямо к его порогу. Вот это была битва!'),
(1478, 26, 0, 'ruRU', 'Скажу тебе, Великую войну я совсем не скучаю. Помню, как мы сражались у Дарроумера. Всю ночь в тумане, лёжа в грязном окопе.'),
(1478, 30, 0, 'ruRU', 'Что ж, ты всё ещё здесь. Я бы сказал, за это стоит выпить.'),
(1478, 31, 0, 'ruRU', 'Ты визжал как девчонка, самое смешное, что я видел.'),
(1478, 32, 0, 'ruRU', 'Никогда не видел, чтобы кто-то двигался так быстро.'),
(1478, 33, 0, 'ruRU', 'Давай даже не будем сравнивать боевые шрамы, друг мой.'),
(1478, 34, 0, 'ruRU', 'Хе-хе, слабак.'),
(1478, 35, 0, 'ruRU', 'Ты не перестаёшь удивлять меня тем, что может пережить человек.'),
(1478, 36, 0, 'ruRU', 'В конце концов всё обошлось.'),
(1478, 50, 0, 'ruRU', 'Эй, Риз, налей нам с Кристофом ещё по одной.'),
(1477, 20, 0, 'koKR', '그날 밤의 흉터가 아직도 남아있다네.'),
(1477, 21, 0, 'koKR', '그게 자네의 미친 짓 중 하나를 시도하다가 내가 거의 배가 갈릴 뻔했던 세 번째인가 네 번째였나?'),
(1477, 22, 0, 'koKR', '등에 박힌 쇳조각이 평생 그날 밤을 기억하게 해줄 걸세.'),
(1477, 23, 0, 'koKR', '그래, 그리고 그날 밤 내 손을 직접 사제들에게 가져다줄 수 있게 해줘서 고맙네.'),
(1477, 24, 0, 'koKR', '그날 밤 다리를 둘 다 부러뜨렸지. 어떻게 잊을 수 있겠나?'),
(1477, 25, 0, 'koKR', '내 엄지손가락을 주워서 자네 담배쌈지에 넣어 가지고 다녔던 그날 밤 아니었나?'),
(1477, 26, 0, 'koKR', '세 주 후에 노스쉐어의 침대에서 깨어났지. 아무것도 기억이 안 나.'),
(1477, 50, 0, 'koKR', '따뜻한 술집과 시원한 에일. 이보다 더 바랄 게 있겠나?'),
(1478, 20, 0, 'koKR', '아, 글러스트웰트 쌍둥이!'),
(1478, 21, 0, 'koKR', '늪지에서 황혼의 망치단과 싸울 때, 전쟁하기엔 더 나은 장소들이 떠올랐지.'),
(1478, 22, 0, 'koKR', '로데론의 그 여관에서 마시던 드워프 에일이 그립군. 거기서 시작했던 그 싸움 기억나나?'),
(1478, 23, 0, 'koKR', '우리는 백 명도 안 됐는데, 오크는 천 명이 넘었지. 우리 중 몇 명만이 겨우 살아 돌아왔어.'),
(1478, 24, 0, 'koKR', '다나스가 스톰윈드의 모든 용병들을 모아서 우리가 네더가드로 싸우러 진군했던 거 기억하나?'),
(1478, 25, 0, 'koKR', '제일 좋았던 건 우리 군대가 페레놀드의 집 앞까지 진군했을 때 그의 표정이었지. 정말 대단한 전투였어!'),
(1478, 26, 0, 'koKR', '말해두지만, 난 대전쟁이 전혀 그립지 않아. 다로우메어에서 싸웠던 게 기억나는군. 안개 속에서 진흙투성이 참호에 누워 밤을 새웠지.'),
(1478, 30, 0, 'koKR', '음, 자네는 아직 여기 있군. 그건 축배를 들 만한 일이라고 생각하네.'),
(1478, 31, 0, 'koKR', '자네는 어린 소녀처럼 비명을 질렀지, 내가 본 것 중 제일 웃긴 일이었어.'),
(1478, 32, 0, 'koKR', '평생 그렇게 빨리 움직이는 사람은 본 적이 없다네.'),
(1478, 33, 0, 'koKR', '전투 흉터 비교는 아예 시작도 하지 말자고, 친구.'),
(1478, 34, 0, 'koKR', '히히, 겁쟁이.'),
(1478, 35, 0, 'koKR', '사람이 어떻게 그런 걸 견뎌내는지 자네는 계속 날 놀라게 하는군.'),
(1478, 36, 0, 'koKR', '결국 다 잘 풀렸지.'),
(1478, 50, 0, 'koKR', '이봐 리스, 나랑 크리스토프에게 한 잔씩 더 주게.'),
(1477, 20, 0, 'zhCN', '那晚留下的伤疤我至今还留着。'),
(1477, 21, 0, 'zhCN', '那是我第三次还是第四次差点在你的疯狂举动中被开膛破肚?'),
(1477, 22, 0, 'zhCN', '我背上有块铁片,会让我余生都记得那个夜晚。'),
(1477, 23, 0, 'zhCN', '是啊,还要谢谢你让我那晚自己把断手送到牧师那里。'),
(1477, 24, 0, 'zhCN', '那晚我摔断了两条腿。我怎么可能忘记?'),
(1477, 25, 0, 'zhCN', '是不是那晚我们不得不把我的拇指捡起来装进你的烟袋里?'),
(1477, 26, 0, 'zhCN', '三周后我在诺森海尔的一张床上醒来,什么都不记得了。'),
(1477, 50, 0, 'zhCN', '温暖的酒馆,冰凉的麦酒。我们还能奢求什么呢?'),
(1478, 20, 0, 'zhCN', '啊,格拉斯特维尔特双胞胎!'),
(1478, 21, 0, 'zhCN', '在沼泽地与那帮暮光之锤交战时,我倒觉得有更好的地方可以打仗。'),
(1478, 22, 0, 'zhCN', '我怀念我们在洛丹伦那家旅店喝的矮人麦酒。还记得我们在那儿挑起的那场斗殴吗?'),
(1478, 23, 0, 'zhCN', '我们不到一百人,对上一千多个兽人。只有少数几个人活着走了出来。'),
(1478, 24, 0, 'zhCN', '还记得达纳斯集结了暴风城所有的雇佣兵,我们进军内瑟迦德作战的时候吗?'),
(1478, 25, 0, 'zhCN', '最棒的莫过于我们的军队直接开到佩伦诺德家门口时他脸上的表情。真是一场恶战!'),
(1478, 26, 0, 'zhCN', '告诉你,我一点都不怀念大战。我记得我们在达罗米尔交战的时候。整夜都在雾中,躺在泥泞的战壕里。'),
(1478, 30, 0, 'zhCN', '嗯,你还活着呢。我觉得这值得喝一杯。'),
(1478, 31, 0, 'zhCN', '你尖叫得像个小女孩,我见过最好笑的事。'),
(1478, 32, 0, 'zhCN', '我这辈子从没见过谁跑得那么快。'),
(1478, 33, 0, 'zhCN', '咱们还是别比战伤了,朋友。'),
(1478, 34, 0, 'zhCN', '嘿嘿,懦夫。'),
(1478, 35, 0, 'zhCN', '一个人能撑过那种事,你总是让我大吃一惊。'),
(1478, 36, 0, 'zhCN', '最后一切都圆满解决了。'),
(1478, 50, 0, 'zhCN', '嘿,里斯,再给我和克里斯托夫来一轮。'),
(1477, 20, 0, 'zhTW', '那晚留下的傷疤我至今還留著。'),
(1477, 21, 0, 'zhTW', '那是我第三次還是第四次差點在你的瘋狂舉動中被開膛破肚?'),
(1477, 22, 0, 'zhTW', '我背上有塊鐵片,會讓我餘生都記得那個夜晚。'),
(1477, 23, 0, 'zhTW', '是啊,還要謝謝你讓我那晚自己把斷手送到牧師那裡。'),
(1477, 24, 0, 'zhTW', '那晚我摔斷了兩條腿。我怎麼可能忘記?'),
(1477, 25, 0, 'zhTW', '是不是那晚我們不得不把我的拇指撿起來裝進你的煙袋裡?'),
(1477, 26, 0, 'zhTW', '三週後我在諾森海爾的一張床上醒來,什麼都不記得了。'),
(1477, 50, 0, 'zhTW', '溫暖的酒館,冰涼的麥酒。我們還能奢求什麼呢?'),
(1478, 20, 0, 'zhTW', '啊,格拉斯特維爾特雙胞胎!'),
(1478, 21, 0, 'zhTW', '在沼澤地與那幫暮光之錘交戰時,我倒覺得有更好的地方可以打仗。'),
(1478, 22, 0, 'zhTW', '我懷念我們在洛丹倫那家旅店喝的矮人麥酒。還記得我們在那兒挑起的那場鬥毆嗎?'),
(1478, 23, 0, 'zhTW', '我們不到一百人,對上一千多個獸人。只有少數幾個人活著走了出來。'),
(1478, 24, 0, 'zhTW', '還記得達納斯集結了暴風城所有的傭兵,我們進軍內瑟迦德作戰的時候嗎?'),
(1478, 25, 0, 'zhTW', '最棒的莫過於我們的軍隊直接開到佩倫諾德家門口時他臉上的表情。真是一場惡戰!'),
(1478, 26, 0, 'zhTW', '告訴你,我一點都不懷念大戰。我記得我們在達羅米爾交戰的時候。整夜都在霧中,躺在泥濘的戰壕裡。'),
(1478, 30, 0, 'zhTW', '嗯,你還活著呢。我覺得這值得喝一杯。'),
(1478, 31, 0, 'zhTW', '你尖叫得像個小女孩,我見過最好笑的事。'),
(1478, 32, 0, 'zhTW', '我這輩子從沒見過誰跑得那麼快。'),
(1478, 33, 0, 'zhTW', '咱們還是別比戰傷了,朋友。'),
(1478, 34, 0, 'zhTW', '嘿嘿,懦夫。'),
(1478, 35, 0, 'zhTW', '一個人能撐過那種事,你總是讓我大吃一驚。'),
(1478, 36, 0, 'zhTW', '最後一切都圓滿解決了。'),
(1478, 50, 0, 'zhTW', '嘿,里斯,再給我和克里斯托夫來一輪。');
